// clef-gate: ask a local Clef whether a tool call or subagent is worth paying for.
//
// turn.start remembers the prompt; tool.call and agent.spawn ask Clef and allow or
// deny; turn.complete writes the log. Every failure path lets the call run.

import type { EngineInterface, PluginOptions, Register } from "claude-code"

import { breakerOpenFor, normaliseBreaker, recordFailure, recordSuccess, type BreakerState } from "./lib/breaker.ts"
import { parseAdvancedFile, parseConfig, type Config } from "./lib/config.ts"
import { argsHash, buildAgentState, buildToolState, summariseArgs, TERSE_PROMPT_CHARS, type CallSeen } from "./lib/context.ts"
import { answerLine, HELP, historyReport, statsReport, statusLine, statusReport, type HistoryRow, type TurnCounts } from "./lib/format.ts"
import { aggregate, gateRecord, logFileName, parseLines } from "./lib/log.ts"
import { agentVerdict, denyText, matchesTool, toolVerdict, type Mode, type PolicyConfig } from "./lib/policy.ts"
import { agentQuestions, DEFAULT_RUBRIC, parseRubric, toolQuestions, type Rubric } from "./lib/rubric.ts"
import { decide, type NoulQuestion } from "./lib/systemone.ts"
import type { ClefResult, Decision, GateKind } from "./lib/types.ts"

const PLUGIN = "clef-gate"
const SESSION_REF = { plugin: "clef-gate", key: "session" } as const
const BREAKER_KEY = "breaker"
const HISTORY_LIMIT = 50

type Persisted = {
  sessionMode?: Mode | "off"
  history: HistoryRow[]
  warned: string[]
}

type Turn = {
  turnId: string
  prompt: string
  calls: CallSeen[]
  denied: string[]
  decisions: Decision[]
  counts: TurnCounts
}

let options: PluginOptions = {}
let state: Persisted = { history: [], warned: [] }
let loaded = false
let config: Config = parseConfig({}).config
let problems: string[] = []
let rubric: Rubric = DEFAULT_RUBRIC
let logDir: string | undefined
let advancedPath: string | undefined
let logFile: string | undefined
let logLines: string[] = []
let turn: Turn | undefined
let hint: string | undefined
let clefQueue: Promise<unknown> = Promise.resolve()

function newTurn(turnId: string, prompt: string): Turn {
  return { turnId, prompt, calls: [], denied: [], decisions: [], counts: { checked: 0, denied: 0, wouldDeny: 0 } }
}

function mode(): Mode | "off" {
  if (!config.enabled) return "off"
  return state.sessionMode ?? config.mode
}

function policy(): PolicyConfig {
  const m = mode()
  return { mode: m === "off" ? "shadow" : m, denyThreshold: config.denyThreshold, redundantThreshold: config.redundantThreshold, agentThreshold: config.agentThreshold }
}

async function save($: EngineInterface) {
  await $.state.set(SESSION_REF, JSON.stringify(state)).catch(() => {})
}

async function load($: EngineInterface) {
  if (loaded) return
  loaded = true
  try {
    const home = (await $.env.get("HOME")) ?? (await $.env.get("USERPROFILE")) ?? "."
    const configDir = (await $.env.get("CLAUDE_CONFIG_DIR")) ?? `${home}/.claude`
    advancedPath = (await $.env.get("CLEF_GATE_CONFIG")) ?? `${configDir}/${PLUGIN}.json`
    const advancedText = await $.fs.read(advancedPath).catch(() => undefined)
    const advanced = parseAdvancedFile(typeof advancedText === "string" ? advancedText : undefined)
    const parsed = parseConfig({ ...advanced.values, ...options })
    config = parsed.config
    problems = [...advanced.problems, ...parsed.problems]
    if (config.rubricFile) {
      const text = await $.fs.read(config.rubricFile).catch(() => undefined)
      const r = typeof text === "string" ? parseRubric(text) : { problems: [`cannot read rubric_file ${config.rubricFile}`] }
      if ("rubric" in r) rubric = r.rubric
      else problems.push(...r.problems.map((p) => `${p}; using the built-in rubric`))
    }
    logDir = config.logDir ?? `${configDir}/plugins/data/${PLUGIN}`
    const snapshot = await $.state.get(SESSION_REF)
    if (typeof snapshot.value === "string") state = { history: [], warned: [], ...(JSON.parse(snapshot.value) as Partial<Persisted>) }
  } catch (err) {
    problems.push(`setup: ${err instanceof Error ? err.message : String(err)}`)
  }
}

function warnOnce($: EngineInterface, key: string, text: string) {
  if (state.warned.includes(key)) return
  state.warned.push(key)
  $.ui.toast(text, { timeoutMs: 8000 })
}

function showStatus($: EngineInterface, text: string | undefined) {
  const next = text === undefined ? undefined : `↳ ${text}`
  if (next === hint) return
  hint = next
  $.ui.invalidate("ui.render")
}

function announce($: EngineInterface) {
  if (config.announce !== "status" && config.announce !== "both") return
  const m = mode()
  if (m === "off") return showStatus($, "gate · off")
  showStatus($, statusLine(m, turn?.counts ?? { checked: 0, denied: 0, wouldDeny: 0 }))
}

async function readBreaker($: EngineInterface): Promise<BreakerState> {
  return normaliseBreaker(await $.store.get(BREAKER_KEY).catch(() => undefined))
}

// The local server scores one request at a time. Parallel tool calls would queue
// inside it and the later ones would hit our timeout, so we serialise here.
function askClef($: EngineInterface, stateText: string, questions: Record<string, NoulQuestion>): Promise<ClefResult> {
  const run = clefQueue.then(() => askClefNow($, stateText, questions))
  clefQueue = run.catch(() => undefined)
  return run
}

async function askClefNow($: EngineInterface, stateText: string, questions: Record<string, NoulQuestion>): Promise<ClefResult> {
  const now = await $.clock.now()
  const breaker = await readBreaker($)
  const open = breakerOpenFor(breaker, now)
  if (open !== undefined) return { ok: false, kind: "circuit-open", message: `paused ${open}s after repeated failures`, latencyMs: 0 }
  const result = await decide(
    {
      endpoint: config.endpoint,
      model: config.model,
      timeoutMs: config.timeoutMs,
      fetch: async (url, init) => {
        const r = await $.http.fetch(url, init)
        return { status: r.status, ok: r.ok, text: r.text }
      },
      sleep: (ms, signal) => $.clock.sleep(ms, { signal }),
      now: () => $.clock.now(),
    },
    stateText,
    questions,
  )
  const after = result.ok ? recordSuccess(breaker) : recordFailure(breaker, await $.clock.now())
  await $.store.set(BREAKER_KEY, after).catch(() => {})
  if (!result.ok && result.kind !== "circuit-open")
    warnOnce($, `clef-${result.kind}`, `Clef gate: ${result.kind} talking to ${config.endpoint} (${result.message}). Calls run ungated until it answers.`)
  return result
}

async function lastAssistantText($: EngineInterface): Promise<string | undefined> {
  const rows = await $.session.messages().catch(() => [])
  for (let i = rows.length - 1; i >= 0; i--) {
    const r = rows[i]!
    if (r.role === "assistant" && r.text.trim() !== "") return r.text
  }
  return undefined
}

async function previousUserText($: EngineInterface, current: string): Promise<string | undefined> {
  if (current.trim().length >= TERSE_PROMPT_CHARS) return undefined
  const rows = await $.session.messages().catch(() => [])
  const users = rows.filter((r) => r.role === "user" && r.text.trim() !== "").map((r) => r.text)
  if (users.at(-1)?.trim() === current.trim()) users.pop()
  return users.at(-1)
}

function remember($: EngineInterface, d: Decision, ts: string) {
  if (!turn) return
  d.ts = ts
  turn.decisions.push(d)
  if (d.verdict !== "skip") {
    turn.counts.checked++
    if (d.verdict === "deny") turn.counts.denied++
    if (d.verdict === "would-deny") turn.counts.wouldDeny++
    turn.counts.last = { tool: d.tool, verdict: d.verdict, reason: d.reason }
  }
  state.history.push({ ts, kind: d.kind, tool: d.tool, verdict: d.verdict, reason: d.reason, summary: d.summary })
  while (state.history.length > HISTORY_LIMIT) state.history.shift()
  announce($)
}

async function appendLog($: EngineInterface, lines: string[], ts: string) {
  if (!config.logEnabled || !logDir || lines.length === 0) return
  try {
    const file = `${logDir}/${logFileName(ts, await $.session.id())}`
    if (file !== logFile) {
      logFile = file
      const existing = await $.fs.read(file).catch(() => "")
      logLines = typeof existing === "string" && existing !== "" ? existing.trimEnd().split("\n") : []
    }
    logLines.push(...lines)
    await $.fs.write(file, logLines.join("\n") + "\n")
  } catch {
    // the log must never cost the turn anything
  }
}

async function gate(
  $: EngineInterface,
  kind: GateKind,
  tool: string,
  summary: string,
  hash: string,
  argsChars: number,
  stateText: string,
  questions: Record<string, NoulQuestion>,
): Promise<Decision> {
  const base = { kind, tool, argsHash: hash, argsChars, summary }
  if (turn?.denied.includes(hash)) {
    const v = kind === "tool" ? toolVerdict({}, policy(), true) : agentVerdict({}, policy(), true)
    return { ...base, ...v }
  }
  const result = await askClef($, stateText, questions)
  if (!result.ok) return { ...base, verdict: "fail-open", reason: `${result.kind}: ${result.message}`, result }
  const v = kind === "tool" ? toolVerdict(result.probabilities, policy(), false) : agentVerdict(result.probabilities, policy(), false)
  if (v.verdict === "deny" && turn) turn.denied.push(hash)
  return { ...base, ...v, result }
}

async function statusText($: EngineInterface): Promise<string> {
  const breaker = await readBreaker($)
  const open = breakerOpenFor(breaker, await $.clock.now())
  const m = mode()
  const report = statusReport({
    config,
    configProblems: problems,
    sessionMode: m === "off" ? config.mode : m,
    counts: turn?.counts ?? { checked: 0, denied: 0, wouldDeny: 0 },
    breaker: { calls: breaker.calls, failures: breaker.failures, ...(open !== undefined ? { openForSeconds: open } : {}) },
    ...(logDir ? { logDir } : {}),
    ...(advancedPath ? { advancedPath } : {}),
  })
  return m === "off" && config.enabled ? `${report}\n\nGating is OFF for this session (/gate on resumes).` : report
}

async function statsText($: EngineInterface, days: number): Promise<string> {
  if (!logDir) return "No log directory."
  const now = await $.clock.now()
  const since = new Date(now - (days - 1) * 86_400_000).toISOString().slice(0, 10)
  const entries = await $.fs.list(logDir).catch(() => [])
  const files = entries.filter((f) => /^gate-\d{4}-\d{2}-\d{2}-/.test(f.name) && f.name.slice(5, 15) >= since)
  const records = []
  for (const f of files) {
    const text = await $.fs.read(`${logDir}/${f.name}`).catch(() => "")
    if (typeof text === "string") records.push(...parseLines(text))
  }
  return statsReport(aggregate(records), days, files.length)
}

async function runCommand($: EngineInterface, args: string): Promise<string> {
  await load($)
  const [word = "", rest = ""] = args.trim().split(/\s+/, 2)
  switch (word) {
    case "":
    case "status":
      return statusText($)
    case "help":
      return HELP
    case "history":
      return historyReport(state.history)
    case "stats":
      return statsText($, Math.max(1, Math.min(365, Number(rest) || 7)))
    case "shadow":
    case "deny":
      state.sessionMode = word
      await save($)
      announce($)
      return word === "deny"
        ? "Deny mode for this session: calls Clef rates unnecessary are refused. A repeat of a refused call goes through. /gate shadow to stop refusing."
        : "Shadow mode for this session: decisions are logged and shown, nothing is refused."
    case "off":
      state.sessionMode = "off"
      await save($)
      announce($)
      return "Gating off for this session. /gate on resumes."
    case "on":
      delete state.sessionMode
      await save($)
      announce($)
      return `Gating on (${config.mode} mode, from the plugin config).`
    default:
      return `Unknown: /gate ${word}\n\n${HELP}`
  }
}

function toolArgs(e: Record<string, unknown>): Record<string, unknown> {
  const { tool: _t, tool_use_id: _id, agentId: _a, consent: _c, ...args } = e
  return args
}

function resultChars(r: unknown): number | undefined {
  if (typeof r !== "object" || r === null) return undefined
  const o = r as { text?: unknown; result?: unknown }
  if (typeof o.text === "string") return o.text.length
  if (o.result === undefined) return undefined
  try {
    return JSON.stringify(o.result).length
  } catch {
    return undefined
  }
}

export const register: Register = (on, pluginOptions) => {
  options = pluginOptions
  state = { history: [], warned: [] }
  loaded = false
  hint = undefined
  turn = undefined
  clefQueue = Promise.resolve()
  logFile = undefined
  logLines = []

  on("ui.render", { component: "PromptHint" }, async ($, e, next) => {
    if (hint === undefined) return next(e)
    const tail = e.props.tail ? `${e.props.tail} · ${hint}` : `  ${hint}`
    return next({ ...e, props: { ...e.props, tail } })
  })

  on("session.start", async ($, e, next) => {
    await load($)
    await $.command
      .register({
        name: "gate",
        description: "Clef gate: status, history, stats, shadow, deny, on, off",
        argumentHint: "[status|history|stats [days]|shadow|deny|on|off|help]",
        immediate: true,
      })
      .catch(() => {})
    announce($)
    return next(e)
  })

  on("session.end", async ($, e, next) => {
    if (e.reason === "clear") {
      turn = undefined
      state.history = []
      logFile = undefined
      await save($)
      announce($)
    }
    return next(e)
  })

  on("turn.start", async ($, e, next) => {
    try {
      await load($)
      turn = newTurn(e.turnId, e.text)
      announce($)
    } catch {
      // ungated turn
    }
    return next(e)
  })

  on("tool.call", async ($, e, next) => {
    let decision: Decision | undefined
    try {
      await load($)
      const m = mode()
      if (m === "off" || !matchesTool(e.tool, config.tools) || (e.agentId !== undefined && !config.gateInSubagents) || !turn) return next(e)
      const args = toolArgs(e as unknown as Record<string, unknown>)
      const summary = summariseArgs(e.tool, args)
      const hash = await argsHash(e.tool, args)
      const stateText = buildToolState({
        prompt: turn.prompt,
        calls: turn.calls,
        lastAssistant: await lastAssistantText($),
        previousRequest: await previousUserText($, turn.prompt),
        tool: e.tool,
        summary,
        maxChars: config.maxStateChars,
        recentCalls: config.recentCalls,
      })
      decision = await gate($, "tool", e.tool, summary, hash, JSON.stringify(args).length, stateText, toolQuestions(rubric))
    } catch {
      decision = undefined
    }
    if (!decision) return next(e)
    const ts = new Date(await $.clock.now()).toISOString()
    if (decision.verdict === "deny") {
      remember($, decision, ts)
      turn?.calls.push({ tool: e.tool, summary: decision.summary, verdict: "deny" })
      return { deny: denyText("tool", decision.result?.ok ? decision.result.probabilities : {}) }
    }
    const ran = await next(e)
    const chars = ran.deny === undefined ? resultChars(ran) : undefined
    if (chars !== undefined) decision.resultChars = chars
    remember($, decision, ts)
    turn?.calls.push({ tool: e.tool, summary: decision.summary, verdict: decision.verdict, ...(chars !== undefined ? { resultChars: chars } : {}) })
    return ran
  })

  on("agent.spawn", async ($, e, next) => {
    let decision: Decision | undefined
    try {
      await load($)
      if (mode() === "off" || !config.gateSubagents || e.fork || e.parentAgentId !== undefined || !turn) return next(e)
      const args = { subagent_type: e.subagentType, description: e.description, prompt: e.prompt }
      const summary = summariseArgs("Agent", args)
      const hash = await argsHash("Agent", args)
      const stateText = buildAgentState({
        prompt: turn.prompt,
        calls: turn.calls,
        previousRequest: await previousUserText($, turn.prompt),
        subagentType: e.subagentType,
        description: e.description,
        agentPrompt: e.prompt,
        maxChars: config.maxStateChars,
        recentCalls: config.recentCalls,
      })
      decision = await gate($, "agent", e.subagentType, summary, hash, JSON.stringify(args).length, stateText, agentQuestions(rubric))
    } catch {
      decision = undefined
    }
    if (!decision) return next(e)
    const ts = new Date(await $.clock.now()).toISOString()
    remember($, decision, ts)
    if (decision.verdict === "deny") {
      turn?.calls.push({ tool: "Agent", summary: decision.summary, verdict: "deny" })
      return { deny: denyText("agent", decision.result?.ok ? decision.result.probabilities : {}) }
    }
    turn?.calls.push({ tool: "Agent", summary: decision.summary, verdict: decision.verdict })
    return next(e)
  })

  on("turn.complete", async ($, e, next) => {
    const result = await next(e)
    if (e.agentId !== undefined || !turn || turn.turnId !== e.turnId) return result
    try {
      const ts = new Date(await $.clock.now()).toISOString()
      const session = await $.session.id()
      const m = mode()
      const logMode: Mode = m === "off" ? config.mode : m
      const t = turn
      await appendLog($, t.decisions.map((d) => JSON.stringify(gateRecord({ decision: d, session, turn: t.turnId, ts, mode: logMode, logText: config.logPrompts }))), ts)
      await save($)
      if ((config.announce === "answer" || config.announce === "both") && m !== "off") {
        const line = answerLine(m, t.counts)
        if (line) return { ...result, text: line }
      }
    } catch {
      // logging only
    }
    return result
  })

  on("command.run", { command: "gate" }, async ($, e) => ({ text: await runCommand($, e.args) }))
}

