export type BreakerState = {
  calls: number
  failures: number
  consecutiveFailures: number
  pausedUntil?: number
}

export const BREAKER = { threshold: 3, pauseMs: 5 * 60_000 }

export function freshBreaker(): BreakerState {
  return { calls: 0, failures: 0, consecutiveFailures: 0 }
}

export function normaliseBreaker(value: unknown): BreakerState {
  if (typeof value !== "object" || value === null) return freshBreaker()
  const s = value as Partial<BreakerState>
  if (typeof s.calls !== "number" || typeof s.failures !== "number" || typeof s.consecutiveFailures !== "number") return freshBreaker()
  const out: BreakerState = { calls: s.calls, failures: s.failures, consecutiveFailures: s.consecutiveFailures }
  if (typeof s.pausedUntil === "number") out.pausedUntil = s.pausedUntil
  return out
}

export function breakerOpenFor(s: BreakerState, now: number): number | undefined {
  if (s.pausedUntil !== undefined && s.pausedUntil > now) return Math.ceil((s.pausedUntil - now) / 1000)
  return undefined
}

export function recordSuccess(s: BreakerState): BreakerState {
  return { calls: s.calls + 1, failures: s.failures, consecutiveFailures: 0 }
}

export function recordFailure(s: BreakerState, now: number): BreakerState {
  const next: BreakerState = { calls: s.calls + 1, failures: s.failures + 1, consecutiveFailures: s.consecutiveFailures + 1 }
  if (next.consecutiveFailures >= BREAKER.threshold) next.pausedUntil = now + BREAKER.pauseMs
  return next
}

