// Bad values fall back to defaults and get reported; nothing here throws.

import type { Mode } from "./policy.ts"

export const MODES = ["shadow", "deny"] as const
export const ANNOUNCE_MODES = ["status", "answer", "both", "off"] as const
export type AnnounceMode = (typeof ANNOUNCE_MODES)[number]

export type Config = {
  enabled: boolean
  mode: Mode
  endpoint: string
  model: string
  tools: string[]
  gateSubagents: boolean
  announce: AnnounceMode
  logPrompts: boolean
  denyThreshold: number
  redundantThreshold: number
  agentThreshold: number
  timeoutMs: number
  maxStateChars: number
  recentCalls: number
  gateInSubagents: boolean
  logEnabled: boolean
  logDir?: string
  rubricFile?: string
}

export const DEFAULTS = {
  mode: "shadow" as Mode,
  endpoint: "http://127.0.0.1:8080/v1/systemone",
  model: "clef-flash",
  tools: ["WebFetch", "WebSearch"],
  announce: "status" as AnnounceMode,
  denyThreshold: 0.2,
  redundantThreshold: 0.8,
  agentThreshold: 0.2,
  timeoutMs: 6000,
  maxStateChars: 2400,
  recentCalls: 8,
}

type Options = Readonly<Record<string, unknown>>

function str(o: Options, key: string): string | undefined {
  const v = o[key]
  return typeof v === "string" && v.trim() !== "" ? v.trim() : undefined
}

function numIn(o: Options, key: string, min: number, max: number, fallback: number, problems: string[]): number {
  const v = o[key]
  if (v === undefined || v === "") return fallback
  const n = typeof v === "number" ? v : Number(v)
  if (!Number.isFinite(n) || n < min || n > max) {
    problems.push(`${key} must be a number from ${min} to ${max}; using ${fallback}`)
    return fallback
  }
  return n
}

function oneOf<T extends string>(o: Options, key: string, allowed: readonly T[], fallback: T, problems: string[]): T {
  const v = str(o, key)
  if (v === undefined) return fallback
  if ((allowed as readonly string[]).includes(v)) return v as T
  problems.push(`${key} must be one of ${allowed.join(", ")}; using ${fallback}`)
  return fallback
}

function bool(o: Options, key: string, fallback: boolean): boolean {
  const v = o[key]
  if (typeof v === "boolean") return v
  if (v === "true") return true
  if (v === "false") return false
  return fallback
}

function httpUrl(o: Options, key: string, fallback: string, problems: string[]): string {
  const v = str(o, key)
  if (v === undefined) return fallback
  if (/^https?:\/\/\S+$/i.test(v)) return v
  problems.push(`${key} must be an http:// or https:// URL; using ${fallback}`)
  return fallback
}

function list(o: Options, key: string, fallback: readonly string[]): string[] {
  const v = str(o, key)
  if (v === undefined) return [...fallback]
  return [...new Set(v.split(",").map((s) => s.trim()).filter(Boolean))]
}

export function parseAdvancedFile(text: string | undefined): { values: Options; problems: string[] } {
  if (text === undefined) return { values: {}, problems: [] }
  try {
    const value = JSON.parse(text) as unknown
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      return { values: {}, problems: ["clef-gate.json must hold a JSON object; ignoring it"] }
    }
    return { values: { ...(value as Record<string, unknown>) }, problems: [] }
  } catch {
    return { values: {}, problems: ["clef-gate.json is not valid JSON; ignoring it"] }
  }
}

export function parseConfig(o: Options): { config: Config; problems: string[] } {
  const problems: string[] = []
  const config: Config = {
    enabled: bool(o, "enabled", true),
    mode: oneOf(o, "mode", MODES, DEFAULTS.mode, problems),
    endpoint: httpUrl(o, "endpoint", DEFAULTS.endpoint, problems),
    model: str(o, "model") ?? DEFAULTS.model,
    tools: list(o, "tools", DEFAULTS.tools),
    gateSubagents: bool(o, "gate_subagents", true),
    announce: oneOf(o, "announce", ANNOUNCE_MODES, DEFAULTS.announce, problems),
    logPrompts: bool(o, "log_prompts", false),
    denyThreshold: numIn(o, "deny_threshold", 0, 1, DEFAULTS.denyThreshold, problems),
    redundantThreshold: numIn(o, "redundant_threshold", 0, 1, DEFAULTS.redundantThreshold, problems),
    agentThreshold: numIn(o, "agent_threshold", 0, 1, DEFAULTS.agentThreshold, problems),
    timeoutMs: numIn(o, "timeout_ms", 100, 9_000, DEFAULTS.timeoutMs, problems),
    maxStateChars: numIn(o, "max_state_chars", 400, 60_000, DEFAULTS.maxStateChars, problems),
    recentCalls: numIn(o, "recent_calls", 0, 50, DEFAULTS.recentCalls, problems),
    gateInSubagents: bool(o, "gate_in_subagents", false),
    logEnabled: bool(o, "log_enabled", true),
  }
  const logDir = str(o, "log_dir")
  if (logDir) config.logDir = logDir
  const rubricFile = str(o, "rubric_file")
  if (rubricFile) config.rubricFile = rubricFile
  return { config, problems }
}

