import type { Verdict } from "./types.ts"

export type CallSeen = {
  tool: string
  summary: string
  verdict: Verdict
  resultChars?: number
}

const SECRETS: readonly RegExp[] = [
  /Bearer\s+[A-Za-z0-9._~+/=-]+/gi,
  /(authorization|api[_-]?token|api[_-]?key|secret|password|token)(["']?\s*[:=]\s*["']?)(?!Bearer\s)[^\s"',}]+/gi,
  /\b[A-Za-z0-9_-]{32,}\b/g,
]

export function redact(text: string): string {
  let out = text.replace(SECRETS[0]!, "Bearer [redacted]")
  out = out.replace(SECRETS[1]!, (_m, key: string, sep: string) => `${key}${sep}[redacted]`)
  return out.replace(SECRETS[2]!, "[redacted]")
}

// Head 75%, tail 25%. The intent is usually at one end of a long prompt.
export function truncate(text: string, maxChars: number): string {
  if (text.length <= maxChars) return text
  const head = Math.floor(maxChars * 0.75)
  const tail = maxChars - head
  return `${text.slice(0, head)}\n[... ${text.length - head - tail} characters omitted ...]\n${text.slice(text.length - tail)}`
}

function str(v: unknown, max = 200): string {
  if (typeof v !== "string") return ""
  return v.length > max ? `${v.slice(0, max)}…` : v
}

export function stableStringify(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`
  if (typeof value === "object" && value !== null) {
    const o = value as Record<string, unknown>
    return `{${Object.keys(o).sort().map((k) => `${JSON.stringify(k)}:${stableStringify(o[k])}`).join(",")}}`
  }
  return JSON.stringify(value) ?? "null"
}

export function summariseArgs(tool: string, args: Record<string, unknown>): string {
  let s: string
  switch (tool) {
    case "WebFetch":
      s = `${str(args.url, 300)} — ${str(args.prompt)}`
      break
    case "WebSearch":
      s = `query: ${str(args.query, 300)}`
      break
    case "Read":
    case "Write":
    case "Edit":
      s = str(args.file_path, 300)
      break
    case "Bash":
      s = str(args.command)
      break
    case "Grep":
    case "Glob":
      s = `${str(args.pattern)}${args.path ? ` in ${str(args.path, 120)}` : ""}`
      break
    case "Agent":
      s = `${str(args.subagent_type, 60) || "agent"}: ${str(args.description, 120)} — ${str(args.prompt)}`
      break
    default: {
      const json = stableStringify(args)
      s = json.length > 400 ? `${json.slice(0, 400)}…` : json
    }
  }
  return redact(s.replace(/\s+/g, " ").trim())
}

export async function argsHash(tool: string, args: Record<string, unknown>): Promise<string> {
  const bytes = new TextEncoder().encode(`${tool}\n${stableStringify(args)}`)
  const digest = await crypto.subtle.digest("SHA-256", bytes)
  return Array.from(new Uint8Array(digest).slice(0, 8), (b) => b.toString(16).padStart(2, "0")).join("")
}

function callLines(calls: readonly CallSeen[], recent: number): string[] {
  const shown = recent > 0 ? calls.slice(-recent) : []
  if (shown.length === 0) return ["Earlier in this turn the agent called: nothing yet."]
  return [
    "Earlier in this turn the agent called:",
    ...shown.map((c) => `- ${c.tool}: ${c.summary}${c.resultChars !== undefined ? ` → ${c.resultChars} chars` : ""}${c.verdict === "deny" ? " (refused)" : ""}`),
  ]
}

// "go ahead" or "yes" says nothing about the task, so the previous request has to come along.
export const TERSE_PROMPT_CHARS = 50

function requestLines(prompt: string, previous: string | undefined, budget: number): string {
  const current = truncate(redact(prompt), budget)
  if (!previous || previous.trim() === "" || prompt.trim().length >= TERSE_PROMPT_CHARS) return `User request: ${current}`
  return `Previous request: ${truncate(redact(previous), Math.max(200, Math.floor(budget / 2)))}\nUser request (a short follow-up): ${current}`
}

type StateArgs = {
  prompt: string
  calls: readonly CallSeen[]
  maxChars: number
  recentCalls: number
  previousRequest?: string
}

export function buildToolState(a: StateArgs & { lastAssistant?: string; tool: string; summary: string }): string {
  const tail = [
    ...callLines(a.calls, a.recentCalls),
    ...(a.lastAssistant ? [`Last assistant text: ${redact(str(a.lastAssistant, 400))}`] : []),
    `Proposed call: ${a.tool} — ${a.summary}`,
  ].join("\n")
  return `${requestLines(a.prompt, a.previousRequest, Math.max(200, a.maxChars - tail.length))}\n\n${tail}`
}

export function buildAgentState(a: StateArgs & { subagentType: string; description: string; agentPrompt: string }): string {
  const tail = [
    ...callLines(a.calls, a.recentCalls),
    `Proposed subagent: ${a.subagentType} — ${redact(str(a.description, 200))}`,
    `Subagent task: ${redact(str(a.agentPrompt, 600))}`,
  ].join("\n")
  return `${requestLines(a.prompt, a.previousRequest, Math.max(200, a.maxChars - tail.length))}\n\n${tail}`
}

