import type { Config } from "./config.ts"
import type { Stats } from "./log.ts"
import { pct, type Mode } from "./policy.ts"
import type { GateKind, Verdict } from "./types.ts"

export type TurnCounts = {
  checked: number
  denied: number
  wouldDeny: number
  last?: { tool: string; verdict: Verdict; reason: string }
}

function lastNote(c: TurnCounts): string {
  if (!c.last || (c.last.verdict !== "deny" && c.last.verdict !== "would-deny")) return ""
  const p = /(\d+)%/.exec(c.last.reason)?.[1]
  return ` (${c.last.tool}${p ? ` ${p}%` : ""})`
}

export function statusLine(mode: Mode, c: TurnCounts): string {
  if (c.checked === 0) return `gate · ${mode} · awaiting calls`
  const parts = [`gate · ${mode} · ${c.checked} checked`]
  if (c.denied > 0) parts.push(`${c.denied} denied`)
  if (c.wouldDeny > 0) parts.push(`${c.wouldDeny} would deny`)
  return parts.join(" · ") + lastNote(c)
}

export function answerLine(mode: Mode, c: TurnCounts): string | undefined {
  return c.checked === 0 ? undefined : statusLine(mode, c)
}

export type HistoryRow = { ts: string; kind: GateKind; tool: string; verdict: Verdict; reason: string; summary: string }

export function historyReport(rows: readonly HistoryRow[]): string {
  if (rows.length === 0) return "No gated calls this session."
  const lines = ["Gate decisions this session (newest last)"]
  for (const r of rows) {
    lines.push(`  ${r.ts.slice(11, 19)}  ${r.verdict.padEnd(10)} ${r.kind === "agent" ? "agent " : "tool  "} ${r.tool} · ${r.reason}`)
    lines.push(`             ${r.summary.slice(0, 110)}`)
  }
  return lines.join("\n")
}

export type StatusArgs = {
  config: Config
  configProblems: readonly string[]
  sessionMode: Mode
  counts: TurnCounts
  breaker: { calls: number; failures: number; openForSeconds?: number }
  logDir?: string
  advancedPath?: string
}

export function statusReport(a: StatusArgs): string {
  const c = a.config
  const lines = ["Clef gate"]
  lines.push(`  mode      ${c.enabled ? a.sessionMode : "disabled in plugin config"}${a.sessionMode !== c.mode ? ` (this session; config says ${c.mode})` : ""}`)
  lines.push(`  decider   ${c.model} at ${c.endpoint} · timeout ${c.timeoutMs} ms · state ≤ ${c.maxStateChars} chars`)
  lines.push(`  tools     ${c.tools.join(", ") || "(none)"}${c.gateSubagents ? " · subagent spawns" : ""}${c.gateInSubagents ? " · inside subagents too" : ""}`)
  lines.push(`  thresholds deny when needed < ${pct(c.denyThreshold)}, or needed < 50% and already in context ≥ ${pct(c.redundantThreshold)}; subagent when warranted < ${pct(c.agentThreshold)}`)
  lines.push(`  clef      ${a.breaker.calls} calls · ${a.breaker.failures} failures${a.breaker.openForSeconds !== undefined ? ` · paused ${a.breaker.openForSeconds}s after repeated failures` : ""}`)
  lines.push(`  this turn ${statusLine(a.sessionMode, a.counts)}`)
  for (const p of a.configProblems) lines.push(`  config!   ${p}`)
  if (a.advancedPath) lines.push("", `Advanced settings: ${a.advancedPath} (optional)`)
  lines.push(`Log: ${c.logEnabled ? (a.logDir ?? "(unavailable)") : "off"}${c.logEnabled && c.logPrompts ? " (with prompt and argument text)" : ""}`)
  lines.push("Commands: /gate history · stats [days] · shadow · deny · on · off · help")
  return lines.join("\n")
}

export function statsReport(s: Stats, days: number, files: number): string {
  const lines = [`Clef gate, last ${days} day${days === 1 ? "" : "s"} (${files} log file${files === 1 ? "" : "s"})`]
  if (s.events === 0) {
    lines.push("  No gated calls in this period.")
    return lines.join("\n")
  }
  lines.push(`  events    ${s.events} · ${Object.entries(s.byVerdict).map(([k, v]) => `${k} ${v}`).join(" · ")}`)
  for (const [tool, t] of Object.entries(s.byTool).sort((a, b) => b[1].checked - a[1].checked)) {
    lines.push(`  ${tool.padEnd(22)} ${t.checked} checked · ${t.allowed} allowed · ${t.denied} denied · ${t.wouldDeny} would deny${t.meanResultChars !== undefined ? ` · mean result ${t.meanResultChars} chars` : ""}`)
  }
  if (s.latency) lines.push(`  clef      ${s.clefCalls} calls · latency mean ${s.latency.mean} ms · p50 ${s.latency.p50} ms · p95 ${s.latency.p95} ms`)
  if (Object.keys(s.failures).length > 0) lines.push(`  failures  ${Object.entries(s.failures).map(([k, v]) => `${k} ${v}`).join(" · ")}`)
  lines.push(`  saved     ~${s.estimatedSavedTokens} tokens denied · ~${s.estimatedWouldSaveTokens} tokens would have been denied in deny mode (estimates from mean result sizes)`)
  return lines.join("\n")
}

