import type { Mode } from "./policy.ts"
import type { Decision, GateKind, Probabilities, Verdict } from "./types.ts"

export const LOG_VERSION = 1

export type GateRecord = {
  v: 1
  type: GateKind
  ts: string
  session: string
  turn: string
  tool: string
  argsHash: string
  argsChars: number
  args?: string
  mode: Mode
  verdict: Verdict
  reason?: string
  probabilities?: Probabilities
  latencyMs?: number
  clefInputTokens?: number
  resultChars?: number
  failure?: { kind: string; message: string }
}

export function gateRecord(args: { decision: Decision; session: string; turn: string; ts: string; mode: Mode; logText: boolean }): GateRecord {
  const d = args.decision
  const r: GateRecord = {
    v: LOG_VERSION,
    type: d.kind,
    ts: d.ts ?? args.ts,
    session: args.session,
    turn: args.turn,
    tool: d.tool,
    argsHash: d.argsHash,
    argsChars: d.argsChars,
    mode: args.mode,
    verdict: d.verdict,
    reason: d.reason,
  }
  if (args.logText) r.args = d.summary
  if (d.result?.ok) {
    r.probabilities = { ...d.result.probabilities }
    r.latencyMs = d.result.latencyMs
    if (d.result.inputTokens !== undefined) r.clefInputTokens = d.result.inputTokens
  } else if (d.result) {
    r.failure = { kind: d.result.kind, message: d.result.message }
    if (d.result.latencyMs > 0) r.latencyMs = d.result.latencyMs
  }
  if (d.resultChars !== undefined) r.resultChars = d.resultChars
  return r
}

export function logFileName(ts: string, session: string): string {
  const safe = session.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 12) || "session"
  return `gate-${ts.slice(0, 10)}-${safe}.jsonl`
}

export function parseLines(text: string): GateRecord[] {
  const out: GateRecord[] = []
  for (const line of text.split("\n")) {
    if (line.trim() === "") continue
    try {
      const v = JSON.parse(line) as GateRecord
      if (v && typeof v === "object" && (v.type === "tool" || v.type === "agent")) out.push(v)
    } catch {
      // a torn line from a crash mid-write
    }
  }
  return out
}

export type ToolStats = {
  checked: number
  allowed: number
  denied: number
  wouldDeny: number
  meanResultChars?: number
}

export type Stats = {
  events: number
  byVerdict: Record<string, number>
  byTool: Record<string, ToolStats>
  clefCalls: number
  latency?: { mean: number; p50: number; p95: number }
  failures: Record<string, number>
  estimatedSavedTokens: number
  estimatedWouldSaveTokens: number
}

// Stands in for a tool that never ran under the gate, so a saving can still be guessed.
export const DEFAULT_RESULT_CHARS = 4000

function quantile(sorted: number[], q: number): number {
  if (sorted.length === 0) return 0
  return sorted[Math.min(sorted.length - 1, Math.max(0, Math.ceil(q * sorted.length) - 1))]!
}

function bump(map: Record<string, number>, key: string) {
  map[key] = (map[key] ?? 0) + 1
}

export function aggregate(records: readonly GateRecord[]): Stats {
  const stats: Stats = { events: 0, byVerdict: {}, byTool: {}, clefCalls: 0, failures: {}, estimatedSavedTokens: 0, estimatedWouldSaveTokens: 0 }
  const latencies: number[] = []
  const sizes: Record<string, number[]> = {}
  for (const r of records) {
    stats.events++
    bump(stats.byVerdict, r.verdict)
    const t = (stats.byTool[r.tool] ??= { checked: 0, allowed: 0, denied: 0, wouldDeny: 0 })
    if (r.verdict !== "skip") t.checked++
    if (r.verdict === "allow" || r.verdict === "override" || r.verdict === "fail-open") {
      t.allowed++
      if (r.resultChars !== undefined) (sizes[r.tool] ??= []).push(r.resultChars)
    }
    if (r.verdict === "deny") t.denied++
    if (r.verdict === "would-deny") t.wouldDeny++
    const asked = r.probabilities || r.failure
    if (asked) stats.clefCalls++
    if (asked && r.latencyMs !== undefined) latencies.push(r.latencyMs)
    if (r.failure) bump(stats.failures, r.failure.kind)
  }
  for (const [tool, t] of Object.entries(stats.byTool)) {
    const s = sizes[tool]
    if (s && s.length > 0) t.meanResultChars = Math.round(s.reduce((a, b) => a + b, 0) / s.length)
    const perCall = (t.meanResultChars ?? DEFAULT_RESULT_CHARS) / 4
    stats.estimatedSavedTokens += Math.round(t.denied * perCall)
    stats.estimatedWouldSaveTokens += Math.round(t.wouldDeny * perCall)
  }
  if (latencies.length > 0) {
    const sorted = [...latencies].sort((a, b) => a - b)
    stats.latency = { mean: Math.round(sorted.reduce((s, x) => s + x, 0) / sorted.length), p50: quantile(sorted, 0.5), p95: quantile(sorted, 0.95) }
  }
  return stats
}

