import type { GateKind, Probabilities, Verdict } from "./types.ts"

export type Mode = "shadow" | "deny"

export type PolicyConfig = {
  mode: Mode
  denyThreshold: number
  redundantThreshold: number
  agentThreshold: number
}

export function pct(p: number): string {
  return `${Math.round(p * 100)}%`
}

export function matchesTool(tool: string, patterns: readonly string[]): boolean {
  return patterns.some((p) => (p.endsWith("*") ? tool.startsWith(p.slice(0, -1)) : tool === p))
}

type Ruling = { verdict: Verdict; reason: string }

const OVERRIDE: Ruling = { verdict: "override", reason: "repeated after a refusal this turn; let through" }

function refuse(cfg: PolicyConfig, reason: string): Ruling {
  return { verdict: cfg.mode === "deny" ? "deny" : "would-deny", reason }
}

export function toolVerdict(p: Probabilities, cfg: PolicyConfig, alreadyDenied: boolean): Ruling {
  if (alreadyDenied) return OVERRIDE
  const needed = p.needed ?? 1
  const redundant = p.redundant ?? 0
  if (needed < cfg.denyThreshold) return refuse(cfg, `needed ${pct(needed)} < ${pct(cfg.denyThreshold)}`)
  if (needed < 0.5 && redundant >= cfg.redundantThreshold) return refuse(cfg, `needed ${pct(needed)}, already in context ${pct(redundant)}`)
  return { verdict: "allow", reason: `needed ${pct(needed)}` }
}

export function agentVerdict(p: Probabilities, cfg: PolicyConfig, alreadyDenied: boolean): Ruling {
  if (alreadyDenied) return OVERRIDE
  const warranted = p.warranted ?? 1
  if (warranted < cfg.agentThreshold) return refuse(cfg, `warranted ${pct(warranted)} < ${pct(cfg.agentThreshold)}`)
  return { verdict: "allow", reason: `warranted ${pct(warranted)}` }
}

export function denyText(kind: GateKind, p: Probabilities): string {
  if (kind === "agent") {
    return (
      `clef-gate: starting a subagent looks unnecessary for this task (warranted ${pct(p.warranted ?? 0)}). ` +
      "Do the work directly with a few tool calls. If a subagent is needed after all, call Agent again with the same task and it will go through."
    )
  }
  return (
    `clef-gate: this call looks unnecessary for the current request (needed ${pct(p.needed ?? 0)}, already in context ${pct(p.redundant ?? 0)}). ` +
    "Use what is already in the conversation. If it is needed after all, make the same call again and it will go through."
  )
}

