function check(name: string, value: unknown): string[] {
  if (typeof value !== "object" || value === null) return [`\`${name}\` must be an object`]
  const q = value as Record<string, unknown>
  const problems: string[] = []
  if (typeof q.instructions !== "string" || q.instructions.trim() === "") problems.push(`\`${name}.instructions\` must be a non-empty string`)
  const c = q.criteria as Record<string, unknown> | undefined
  if (typeof c !== "object" || c === null || typeof c.true !== "string" || typeof c.false !== "string")
    problems.push(`\`${name}.criteria\` must have string \`true\` and \`false\``)
  return problems
}

export function parseRubric(text: string): { rubric: Rubric } | { problems: string[] } {
  let value: unknown
