    value = JSON.parse(text)
  } catch {
    return { problems: ["rubric file is not valid JSON"] }
  }
  if (typeof value !== "object" || value === null) return { problems: ["rubric must be a JSON object"] }
  const v = value as Record<string, unknown>
  const problems = [...check("needed", v.needed), ...check("redundant", v.redundant), ...check("warranted", v.warranted)]
  if (problems.length > 0) return { problems }
  return { rubric: v as unknown as Rubric }
}

