// POST /v1/systemone, as llama-server and Ollama serve it for Clef.

import type { ClefFailure, ClefResult, Probabilities } from "./types.ts"

export type NoulQuestion = {
  type: "noul"
  instructions: string
  criteria?: { true: string; false: string }
}

export type HttpLike = (
  url: string,
  init: { method: string; headers: Record<string, string>; body: string },
) => Promise<{ status: number; ok: boolean; text: string }>

export type SystemOneOptions = {
  endpoint: string
  model: string
  timeoutMs: number
  fetch: HttpLike
  sleep: (ms: number, signal: AbortSignal) => Promise<void>
  now: () => number | Promise<number>
}

export function buildRequest(model: string, state: string, questions: Record<string, NoulQuestion>): string {
  return JSON.stringify({ model, state, questions })
}

function num(v: unknown): number | undefined {
  return typeof v === "number" && Number.isFinite(v) ? v : undefined
}

// llama.cpp answers `noul`, Workers AI `probability_true`; older builds put it under `probabilities`.
function pTrue(answer: unknown): number | undefined {
  if (typeof answer !== "object" || answer === null) return undefined
  const a = answer as Record<string, unknown>
  let p = num(a.noul) ?? num(a.probability_true)
  if (p === undefined && a.probabilities && typeof a.probabilities === "object" && !Array.isArray(a.probabilities)) {
    const m = a.probabilities as Record<string, unknown>
    p = num(m.true) ?? num(m.yes)
  }
  if (p === undefined && Array.isArray(a.probabilities)) p = num(a.probabilities[0])
  return p === undefined ? undefined : Math.min(1, Math.max(0, p))
}

export function parseAnswers(bodyText: string, ids: readonly string[], latencyMs: number): ClefResult {
  const fail = (message: string): ClefFailure => ({ ok: false, kind: "malformed", message, latencyMs })
  let body: unknown
  try {
    body = JSON.parse(bodyText)
  } catch {
    return fail("response is not JSON")
  }
  if (typeof body !== "object" || body === null) return fail("response is not an object")
  const answers = (body as Record<string, unknown>).answers
  if (typeof answers !== "object" || answers === null) return fail("response has no answers")
  const probabilities: Probabilities = {}
  for (const id of ids) {
    const p = pTrue((answers as Record<string, unknown>)[id])
    if (p === undefined) return fail(`no usable answer for "${id}"`)
    probabilities[id] = p
  }
  const usage = (body as Record<string, unknown>).usage
  const inputTokens = usage && typeof usage === "object" ? num((usage as Record<string, unknown>).input_tokens) : undefined
  const out: ClefResult = { ok: true, probabilities, latencyMs }
  if (inputTokens !== undefined) out.inputTokens = inputTokens
  return out
}

export function classifyHttpFailure(status: number, bodyText: string, latencyMs: number): ClefFailure {
  const text = bodyText.replace(/\s+/g, " ").trim().slice(0, 160)
  const message = text || `HTTP ${status}`
  if (status === 404) {
    return { ok: false, kind: "bad-request", message: `${message} (no /v1/systemone here: needs llama.cpp b11379+ or Ollama 0.35.1+)`, status, latencyMs }
  }
  if (status === 408) return { ok: false, kind: "timeout", message, status, latencyMs }
  if (status >= 500) return { ok: false, kind: "server", message, status, latencyMs }
  if (status >= 400) return { ok: false, kind: "bad-request", message, status, latencyMs }
  return { ok: false, kind: "malformed", message, status, latencyMs }
}

const TIMED_OUT: unique symbol = Symbol("timeout")

export async function decide(opts: SystemOneOptions, state: string, questions: Record<string, NoulQuestion>): Promise<ClefResult> {
  const started = await opts.now()
  const elapsed = async () => Math.round((await opts.now()) - started)
  let response: { status: number; ok: boolean; text: string } | typeof TIMED_OUT
  const timer = new AbortController()
  try {
    const request = opts.fetch(opts.endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: buildRequest(opts.model, state, questions),
    })
    // $.http.fetch has no abort signal, so a late answer is just dropped.
    request.catch(() => {})
    const deadline = opts.sleep(opts.timeoutMs, timer.signal).then(
      (): typeof TIMED_OUT => TIMED_OUT,
      (): typeof TIMED_OUT => TIMED_OUT,
    )
    response = await Promise.race([request, deadline])
  } catch (err) {
    const message = (err instanceof Error ? err.message : String(err)).slice(0, 200)
    return { ok: false, kind: "network", message, latencyMs: await elapsed() }
  } finally {
    timer.abort()
  }
  const latencyMs = await elapsed()
  if (response === TIMED_OUT) return { ok: false, kind: "timeout", message: `no answer within ${opts.timeoutMs} ms`, latencyMs }
  if (!response.ok) return classifyHttpFailure(response.status, response.text, latencyMs)
  return parseAnswers(response.text, Object.keys(questions), latencyMs)
}

